'use strict';
let calculation=null;
const policyDatasets={ecology:{},irrigation:{}};
function currentDatasets(){return policyDatasets[state.operation];}
let calculationError='Loading verified calculations…';
Object.assign(methods.swiss,{subtitle:'Illustrative minimum · assumed Q347',caption:'For illustration, we use the lowest digitized monthly value, 1.95 m³/s, as an assumed Q347 input. Fishy applies the illustrative graduated curve to calculate a candidate minimum. This is not Q347 estimated from daily observations.',caveat:'The conversion coefficients are illustrative, not an adopted Uzbek table or the literal Swiss statutory table. Additions and an accepted natural reference are absent; this is not a complete ecological requirement.'});
Object.assign(methods.site,{name:'Snow trout study',subtitle:'Published Koksu seasonal baseflow',caption:'Hayes et al. (2025) recommend 0.30 m³/s in winter, 0.50 in April–September and 0.40 in October–November for the studied Koksu reach in the Shakhimardan basin. We use those original values with the published Koksu flow pattern in a hypothetical network.',caveat:'This uses a published Koksu seasonal baseflow. The inflow pattern and recommendation now come from the same river; the network still does not reproduce the studied reaches. The study’s hydraulic geometry and spill rule are not transferred. Local WUA, high-quality habitat and ecological status remain unknown.'});
const fmt=(value,digits=2)=>{const n=Number(value),scale=10**digits;const rounded=Math.round((n+Number.EPSILON*Math.max(1,Math.abs(n))*8)*scale)/scale;return rounded.toLocaleString('en-GB',{minimumFractionDigits:digits,maximumFractionDigits:digits});};
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function resultPath(){return `comparison-${stressTest()?'stress-':''}${state.operation}.json`;}
function activeDataset(){return CalculatedData.selectDataset(currentDatasets(),state.forcing,state.basis);}
function stressTest(){return state.forcing==='dry'&&state.basis==='fixed';}
function selectedScenario(){return activeDataset().data.scenarios[state.forcing];}
function kazakhBasis(){return stressTest()?'Normal-year target · stress test':state.forcing==='dry'?'Dry-year target · assumed statistics':'Normal-year target · assumed statistics';}
function methodSubtitle(key){return key==='kazakh'?`Annual-shift component · ${stressTest()?'fixed normal-year target':state.forcing==='dry'?'dry-year target':'normal-year target'}`:key==='swiss'?'Illustrative floor · assumed Q347':'Published baseflow · habitat not modelled';}
function swissScope(){return state.method==='swiss'?'<p class="method-scope-note"><strong>Swiss example:</strong> we use the floor as a hypothetical release target to show what happens downstream. In the report, a floor alone does not establish a delivery obligation. Its separate check on abstraction or withholding is not performed here.</p>':'';}
function kazakhDerivation(){return CalculatedData.kazakhDerivation(currentDatasets(),state.forcing,state.basis);}
function kazakhCopy(){return stressTest()?'Stress test: keep the normal-year ecological target while inflow falls to 50%. This tests an unchanged target under drought; it is not the dry-year calculation.':'Select the ecological target for the assumed water-year class: normal 50 → 75; dry 95 → 97. The seasonal pattern follows the Koksu curve. The annual flow magnitudes are illustrative assumptions, not measured frequency statistics.';}
function targetNote(){return stressTest()?'Kazakh stress test: normal-year target retained.':`Kazakh target: ${state.forcing==='dry'?'dry':'normal'}-year class (illustrative).`;}
function stressControl(){return state.forcing==='dry'?`<label class="stress-option"><input id="fixed-target" type="checkbox" ${stressTest()?'checked':''}> Keep normal-year target (stress test)</label>`:'';}

function scenarioLabel(){return state.forcing==='dry'?'Dry · 50% of curve':'Digitized Koksu curve';}
function profile(key=state.method){return selectedScenario().methods[key];}
function monthMean(values){return CalculatedData.monthlyMeans(selectedScenario().dates,values)[state.month];}
function sumLedger(p,key){return p.ledger.reduce((sum,row)=>sum+row[key],0);}
function deficitDays(p){return p.actualM3s.filter((v,i)=>v+1e-10<p.candidateM3s[i]).length;}
const deliveryColors={green:'#247449',amber:'#946000',red:'#af3633',grey:'#727c80'};
function deliveryStatus(section='R2b'){
  return FlowStatus.assessFlowDelivery(calculation?profile():null,state.month,section);
}
function deliveryBadge(section='R2b'){
  const result=deliveryStatus(section);
  return `<span class="delivery-badge ${result.status}" role="status"><i aria-hidden="true"></i><strong>${esc(section)}</strong> · ${esc(result.label)}</span>`;
}
function operationControl(){return `<div class="operation-control"><div><strong>Allocation at the upstream intake</strong>${segmented('operation',[['ecology','Ecology first'],['irrigation','Upstream irrigation first']])}</div><p>Same inflow, demand and ecological targets. ${state.operation==='ecology'?'Reserve river flow before diverting the remainder to irrigation.':'Serve irrigation first; less water reaches the reservoir and river.'}</p></div>`;}
function deliveryBar(){
  const rows=calculation?profile().ledger.filter(r=>Number(r.date.slice(5,7))-1===state.month):[];
  const irrigation=rows.length?`Irrigation receives ${fmt(rows.reduce((s,r)=>s+r.diversion_litres,0)/1e9,2)} of ${fmt(rows.reduce((s,r)=>s+r.request_litres,0)/1e9,2)} Mm³ requested this month.`:'';
  const cards=['R2a','R2b'].map(section=>{
    const r=deliveryStatus(section),count=r.status==='grey'?r.reason:`${r.instructionShortfallDays}/${r.assessedDays} days below instruction`;
    const mean=rows.length?rows.reduce((s,r)=>s+r[section==='R2a'?'r2a_litres':'downstream_litres'],0)/rows.length/86400000:null;
    return `<div class="delivery-section">${deliveryBadge(section)}${mean===null?'':`<strong class="section-flow">${fmt(mean,3)} m³/s <small>monthly mean</small></strong>`}<span class="delivery-count">${section==='R2a'?'Before':'After'} drainage return · ${esc(count)}</span></div>`;
  }).join('');
  return `${operationControl()}<section class="delivery-bar" aria-label="River flow delivery traffic lights"><div><span class="eyebrow">Flow delivery · ${months[state.month]}</span><div class="delivery-sections">${cards}</div><span class="delivery-context">${methods[state.method].name} · ${scenarioLabel()}${state.method==='kazakh'?` · ${stressTest()?'fixed normal-year target':'year-matched target'}`:''} · ${esc(irrigation)}</span></div><details class="delivery-key"><summary>Colour key</summary><div class="delivery-legend"><span class="green">● Green: candidate met</span><span class="amber">● Amber: candidate missed; instruction met</span><span class="red">● Red: operating instruction missed</span><span class="grey">● Grey: not assessed</span></div><p>Worst daily result in the selected month. Same illustrative target at R2a and R2b; other objects are unassessed. The instruction is the smaller of the target and river inflow after natural losses, before diversion; it is held fixed between priorities and excludes stored-water credit. Colours show quantity delivery, not ecological status or legal fault.</p></details></section>`;
}
const plainSystemFigure=systemFigure;
systemFigure=function(){
  const base=plainSystemFigure();
  const r=deliveryStatus(),a=deliveryStatus('R2a'),land=state.landscape==='landscape';
  const upper=land?'M95 145Q130 180 183 220L229 282':'M95 145L229 283';
  const overlay=`<defs>${['grey',a.status,r.status].filter((v,i,a)=>a.indexOf(v)===i).map(color=>`<marker id="delivery-arrow-${color}" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="3" markerHeight="3" orient="auto"><path d="M0 0L10 5L0 10Z" fill="${deliveryColors[color]}"/></marker>`).join('')}</defs><g class="delivery-overlay" aria-label="Flow delivery: R1 not assessed; R2a ${esc(a.label)}; R2b ${esc(r.label)}"><path d="${upper}" stroke="${deliveryColors.grey}" stroke-width="7" fill="none" marker-end="url(#delivery-arrow-grey)"/><path d="M239 287H329" stroke="${deliveryColors.grey}" stroke-width="7" fill="none" marker-end="url(#delivery-arrow-grey)"/><path d="M429 287H${land?535:539}" stroke="${deliveryColors[a.status]}" stroke-width="7" fill="none" marker-end="url(#delivery-arrow-${a.status})"/><path d="M${land?541:545} 287H681" stroke="${deliveryColors[a.status]}" stroke-width="7" fill="none" marker-end="url(#delivery-arrow-${a.status})"/><path d="M693 287H${land?846:863}" stroke="${deliveryColors[r.status]}" stroke-width="8" fill="none" marker-end="url(#delivery-arrow-${r.status})"/><circle cx="233" cy="287" r="5" fill="#193c40"/><circle cx="687" cy="287" r="5" fill="#193c40"/><circle cx="810" cy="287" r="6" fill="#fffefa" stroke="${deliveryColors[r.status]}" stroke-width="3"/><rect x="710" y="401" width="172" height="23" rx="4" fill="#fffefa"/><text x="796" y="417" text-anchor="middle" style="font-size:11px;fill:${deliveryColors[r.status]}">R2b delivery · ${r.status.toUpperCase()}</text></g>`;
  return base.replace('</svg>',overlay+'</svg>');
};
const plainSystem=system;
system=function(){return plainSystem().replace('<div class="system-layout">',deliveryBar()+`<label class="system-month" for="month">Inspect <strong>${months[state.month]}</strong><input id="month" type="range" min="0" max="11" step="1" value="${state.month}" aria-label="Inspect month"></label><div class="system-layout">`).replace('<section class="panel"><div class="svg-wrap"','<section class="panel"><p class="scroll-cue">Scroll map → to see R2b</p><div class="svg-wrap"');};
function locationStrip(){return `<div class="case-strip"><button class="location" data-view="system" aria-label="Show R2 calculation section in the system"><svg viewBox="0 0 60 36" aria-hidden="true"><path d="M2 26Q15 7 27 20T57 12" fill="none" stroke="#65969c" stroke-width="5"/><path d="M45 4V28" stroke="#264e54" stroke-width="2"/><circle cx="45" cy="16" r="4" fill="#fffefa" stroke="#264e54" stroke-width="2"/></svg><span><strong>R2 · river section R2b</strong><br>Digitized Koksu flow pattern → hypothetical reservoir and irrigation network</span></button>${segmented('forcing',[['normal','Digitized Koksu curve'],['dry','Dry · 50% of curve']])}</div>${deliveryBar()}`;}
function chart(){
  const s=selectedScenario(), monthly=values=>CalculatedData.monthlyMeans(s.dates,values);
  const natural=monthly(s.naturalM3s), inputs={},outputs={};
  for(const key of Object.keys(methods)){inputs[key]=monthly(s.methods[key].rawCandidateM3s);outputs[key]=monthly(s.methods[key].actualM3s);}
  const series=state.layer==='inputs'?inputs:outputs;
  const peak=Math.max(...natural,...Object.values(inputs).flat(),...Object.values(outputs).flat());
  const unit=peak<10?1:50,max=Math.ceil(peak/unit)*unit;
  const x=i=>88+i*78,y=v=>200-v/max*160;
  const path=values=>values.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ');
  const identical=[];
  const keys=Object.keys(methods);
  for(let i=0;i<keys.length;i++)for(let j=i+1;j<keys.length;j++)if(CalculatedData.coincident(series[keys[i]],series[keys[j]]))identical.push(`${methods[keys[i]].name} + ${methods[keys[j]].name}`);
  const drawOrder=keys.filter(k=>k!==state.method).concat(state.method);
  const target=inputs[state.method][state.month],actual=outputs[state.method][state.month];
  return `<div class="chart-head"><div><span class="preview-tag">Monthly curve → daily model steps</span><h2>${state.layer==='inputs'?'Ecological targets':'Delivered river flow at R2b'} · ${scenarioLabel()}</h2></div>${segmented('layer',[['inputs','Ecological targets'],['results','Delivered river flow']])}</div><div class="causal-strip" aria-label="Calculated operational sequence"><span style="color:${methods[state.method].color}">Target at R2a + R2b</span><b>→</b><span>Release + spill + return</span><b>→</b><span>River flow</span><small>${state.operation==='ecology'?'Ecology first':'Irrigation first'}</small></div><div class="chart-legend"><span class="key"><i class="swatch" style="--key:#8b9898"></i>No local management</span>${keys.map(key=>`<span class="key"><i class="swatch" style="--key:${methods[key].color}"></i>${state.layer==='results'?'Delivered flow — ':'Ecological target — '}${methods[key].name}</span>`).join('')}${state.layer==='results'?`<span class="key"><i class="swatch dashed" style="--key:${methods[state.method].color}"></i>Selected ecological target</span>`:''}</div><p class="scroll-cue">Scroll chart → to see all months</p><div class="svg-wrap" tabindex="0" role="region" aria-label="Calculated monthly flow chart"><svg class="seasonal" viewBox="0 0 1030 245" role="img" aria-label="Calculated ${scenarioLabel()} monthly discharge in cubic metres per second. Selected ${methods[state.method].name} ${months[state.month]} ecological target ${fmt(target,3)}; delivered flow at R2b ${fmt(actual,3)}.">${[0,1,2,3,4].map(i=>`<line x1="88" y1="${y(max*i/4)}" x2="946" y2="${y(max*i/4)}" stroke="#e7eae4"/><text x="74" y="${y(max*i/4)+5}" text-anchor="end">${fmt(max*i/4,(max*i/4)%1?2:0)}</text>`).join('')}<text x="24" y="24">m³/s</text><path d="${path(natural)} L946,200 L88,200 Z" fill="#a6b8b0" opacity=".13"/><path d="${path(natural)}" stroke="#8b9898" stroke-width="3" fill="none"/>${drawOrder.map(key=>`<path d="${path(series[key])}" stroke="${methods[key].color}" stroke-width="${key===state.method?4:2.5}" fill="none" stroke-linejoin="round"/>`).join('')}${state.layer==='results'?`<path d="${path(inputs[state.method])}" stroke="${methods[state.method].color}" stroke-width="2.5" stroke-dasharray="7 6" fill="none"/>`:''}<line x1="${x(state.month)}" y1="40" x2="${x(state.month)}" y2="200" stroke="#244f55" opacity=".5" stroke-dasharray="3 5"/>${months.map((m,i)=>`<text x="${x(i)}" y="231" text-anchor="middle">${m}</text>`).join('')}</svg></div><div class="chart-foot"><label for="month">Inspect <strong>${months[state.month]}</strong><input id="month" type="range" min="0" max="11" step="1" value="${state.month}" aria-label="Inspect month"></label><span>Ecological target <strong>${fmt(target,3)}</strong> · Delivered at R2b <strong>${fmt(actual,3)}</strong> m³/s</span><span class="chart-note">${identical.length?'Coincident monthly curves: '+identical.join('; ')+'. ':''}Inflow is held constant within months; plotted flows are monthly means. Dry inflow is an assumed 50%.</span></div>`;
}
function detailFigure(key){
  const p=profile(key),monthly=CalculatedData.monthlyMeans(selectedScenario().dates,p.rawCandidateM3s),maximum=Math.max(...monthly);
  const start=`<svg class="illustration" viewBox="0 0 1000 225" role="img" aria-label="${methods[key].name} calculated candidate in cubic metres per second">`;
  if(key==='site')return `${start}${monthly.map((v,i)=>`<rect x="${35+i*43}" y="${165-v/.5*115}" width="27" height="${v/.5*115}" rx="2" fill="#56815d"/><text x="${48+i*43}" y="187" text-anchor="middle">${months[i]}</text><text x="${48+i*43}" y="${155-v/.5*115}" text-anchor="middle">${fmt(v,1)}</text>`).join('')}<text x="35" y="214" class="small">Published monthly baseflow · m³/s · values retained without scaling</text><text x="615" y="55" class="title">Reported habitat retention in the source study</text><text x="615" y="88" class="small">0.30 m³/s: mean WUA 73% · high-quality 41%</text><text x="615" y="120" class="small">0.50 m³/s: mean WUA 78% · high-quality 63%</text><text x="615" y="158" class="small">Relative to 2 m³/s in the studied reach.</text><text x="615" y="190" class="title">Habitat in this hypothetical network: unknown</text></svg>`;
  const title=key==='swiss'?'Calculated constant candidate':'Calculated seasonal component';
  return `${start}${monthly.map((v,i)=>`<rect x="${35+i*43}" y="${170-v/maximum*115}" width="27" height="${v/maximum*115}" rx="2" fill="${methods[key].color}"/><text x="${48+i*43}" y="193" text-anchor="middle">${months[i]}</text>`).join('')}<text x="35" y="30" class="title">${title} · ${fmt(Math.min(...monthly),3)}–${fmt(maximum,3)} m³/s</text><text x="35" y="218" class="small">Monthly means of the calculated daily candidate</text><text x="615" y="65" class="title">${key==='swiss'?'Assume Q347 input = lowest monthly value':`Annual class ${kazakhDerivation().originalClass}% → ${kazakhDerivation().shiftedClass}%`}</text><text x="615" y="102" class="title">${key==='swiss'?'Illustrative graduated curve → minimum':'Annual mean flow × mean-one seasonal shape'}</text><text x="615" y="149" class="small">${key==='swiss'?'Additions remain to be assessed.':`Assumed Q${kazakhDerivation().shiftedClass} = ${fmt(kazakhDerivation().annualEcologicalM3s,3)} m³/s; full bounds absent.`}</text><text x="615" y="181" class="small">Conditional illustration; not an adopted basin requirement.</text></svg>`;
}
function methodDetail(){
  if(!state.detail)return '';
  const m=methods[state.method],p=profile(),s=selectedScenario(),d=activeDataset().targets.methods[state.method].derivation;
  const derivation=state.method==='swiss'?`Assumed Q347 input ${fmt(d.q347M3s,3)} → illustrative minimum ${fmt(d.candidateM3s,3)} m³/s`:state.method==='kazakh'?`Assumed Q${kazakhDerivation().originalClass} ${fmt(kazakhDerivation().annualReferenceM3s,3)} → Q${kazakhDerivation().shiftedClass} ${fmt(kazakhDerivation().annualEcologicalM3s,3)} m³/s. Percentages identify annual exceedance classes, not shares of today's inflow.`:'Hayes et al. (2025), Table 1 · Koksu, Shakhimardan basin · original source values';
  const rows=p.ledger.filter(r=>Number(r.date.slice(5,7))-1===state.month);
  const average=key=>rows.reduce((sum,r)=>sum+r[key],0)/rows.length/86400000;
  return `<section id="method-detail" class="panel details-panel" style="--key:${m.color}" aria-label="Selected method explanation"><div class="detail-title"><div><p class="eyebrow">Inside the method · evidence and calculation</p><h2>${m.name}</h2></div><button class="plain-button" data-close>Close detail</button></div><p class="detail-copy">${state.method==='kazakh'?kazakhCopy():m.caption}</p>${state.method==='kazakh'?stressControl():''}${swissScope()}<p class="calculation-line">${derivation}</p><div class="svg-wrap" tabindex="0" role="region" aria-label="Method illustration, scroll horizontally on narrow screens">${detailFigure(state.method)}</div><p class="small-note">${months[state.month]} ${scenarioLabel()} model means: boundary ${fmt(average('boundary_litres'))} → natural loss ${fmt(average('natural_loss_litres'))}; diversion ${fmt(average('diversion_litres'))}, return ${fmt(average('return_litres'))}; reservoir release ${fmt(average('release_litres'))} + spill ${fmt(average('spill_litres'))} + return ≈ downstream ${fmt(monthMean(p.actualM3s))} m³/s.</p><details><summary>Source, assumptions and limits</summary><p>${state.method==='kazakh'?'For this illustration only: Q50 = base annual mean; Q75 = 0.8 × Q50; Q95 = 0.5 × Q50; Q97 = 0.4 × Q50. Both classes use the same assumed seasonal shape. These values are not inferred from the twelve monthly medians, and the method does not prescribe these ratios. Full baseline bounds and biological corrections are absent.':m.caveat}</p><p>Inflow: approximate digitisation of Figure 2, Hayes et al. (2025), Koksu monthly medians for 2011–2020. We hold these values constant within each month to create a synthetic 365-day forcing. The dry case multiplies all inflows by 0.5; it is not an observed year. Swiss-derived and snow trout targets remain fixed. The Kazakh target follows the assumed year class unless the fixed-target stress test is selected. Storage: 5 million m³, initially empty; assumed loss: 5%; irrigation request: up to 3 m³/s; half of the diversion returns the same day. The previous 20% diversion cap is removed in both priority cases. The same illustrative target is applied before and after drainage returns; the reservoir aims to deliver it at R2a, without crediting downstream returns. These describe a hypothetical network. The unmanaged comparison retains natural losses and removes only these local operations.</p>${state.method==='site'?'<p><a href="https://doi.org/10.1007/s13762-025-06761-2" target="_blank" rel="noreferrer">Hayes et al. (2025), Table 1 and reported habitat results</a>. Source habitat percentages are exact published points, not an interpolated response curve at this location.</p>':''}<p>Native Taqsim routing; Fishy numerical assessment of hypothetical candidates and operating instructions. Operation rounds each daily candidate volume upward in increments of 2 m³ (less than 0.000024 m³/s). Daily quantities are checked before monthly aggregation. Full ecological requirement and official compliance remain unassessed.</p><p><a href="${resultPath()}" target="_blank">Download daily results and provenance</a> · <a href="${stressTest()?'targets-stress.json':'targets.json'}" target="_blank">Candidate derivations</a></p></details></section>`;
}
function compare(){
  if(!calculation)return `<section class="panel details-panel"><h1>Calculated comparison</h1><p>${esc(calculationError)}</p><p>No schematic result is substituted.</p></section>`;
  const shared=sumLedger(profile(),'diversion_litres')/1e9;
  return `<div class="title-row"><div><p class="eyebrow">Compare methods</p><h1>How does the method change downstream flow?</h1></div></div>${locationStrip()}<section class="panel comparison-grid" aria-label="Method comparison"><div class="chart-column">${chart()}</div><div class="method-column"><p class="method-column-title">Three illustrative components</p><p class="method-scope-note">These are parts of the methods, not complete regimes. Evidence determines which route applies; these buttons compare examples.</p><table class="method-table"><thead><tr><th>Method · select to inspect</th><th>Annual downstream volume</th><th>Final storage</th></tr></thead><tbody>${Object.entries(methods).map(([key,m])=>{const p=profile(key);return `<tr class="${state.method===key?'selected':''}"><td><button class="method-button" data-method="${key}" aria-expanded="${state.detail&&state.method===key}"><span class="method-icon" style="color:${m.color}">${m.icon}</span><span><strong>${m.name}</strong><small>${methodSubtitle(key)}</small></span><span class="method-arrow" aria-hidden="true">⌄</span></button></td><td class="pending" data-label="Annual downstream">${fmt(CalculatedData.annualVolumeMm3(p.actualM3s),1)} Mm³</td><td class="pending" data-label="Final storage">${fmt(p.ledger.at(-1).end_storage_litres/1e9,2)} Mm³</td></tr>`;}).join('')}</tbody></table>${state.detail?'<a class="detail-jump" href="#method-detail">Selected explanation below ↓</a>':'<p class="detail-hint">Select a method to see its source and calculation.</p>'}</div></section><div class="below-note"><span class="dot"></span>${targetNote()} Selected method: ${fmt(shared,2)} Mm³ diverted for irrigation over the year. Water released downstream is not retained in storage.</div>${methodDetail()}`;
}
function assessment(){
  if(!calculation)return compare();
  const p=profile(),rows=p.ledger,s=selectedScenario();
  const issued=rows.map(r=>r.issued_litres/86400000),issuedShort=p.actualM3s.filter((v,i)=>v+1e-10<issued[i]).length;
  return `<div class="title-row"><div><p class="eyebrow">Assessment</p><h1>Compare delivery, then interpret the evidence</h1></div></div>${locationStrip()}<div class="assessment-grid"><section class="panel"><span class="preview-tag">Native model + Fishy · hypothetical criteria</span><h2>${methods[state.method].name} · R2b · ${scenarioLabel()}</h2>${swissScope()}${state.method==='kazakh'?`<p class="small-note">${targetNote()}</p>`:''}<p class="small-note">${months[state.month]} monthly means; daily findings below use all 365 daily values.</p><div class="steps"><div class="step"><em>Candidate</em><b>${fmt(monthMean(p.rawCandidateM3s),3)} m³/s</b><span>Illustrative or published ecological component.</span></div><span class="between" aria-hidden="true">→</span><div class="step"><em>Operating instruction</em><b>${fmt(monthMean(issued),3)} m³/s</b><span>Target limited by river inflow before diversion; unchanged between priorities.</span></div><span class="between" aria-hidden="true">→</span><div class="step"><em>Modelled delivery</em><b>${fmt(monthMean(p.actualM3s),3)} m³/s</b><span>R2b after drainage returns; R2a is assessed separately above.</span></div></div><div class="status-line"><span>Days below candidate</span><b>${deficitDays(p)} / 365</b></div><div class="status-line"><span>Days below operating instruction</span><b>${issuedShort} / 365</b></div><div class="status-line"><span>Daily water-balance residual</span><b>${fmt(Math.max(...rows.map(r=>Math.abs(r.residual_litres))),0)} litres</b></div><div class="status-line"><span>Local habitat / ecological status</span><b>Not established</b></div><p class="small-note">Meeting the published baseflow in a hypothetical network does not reproduce the source study’s habitat results. The published habitat percentages cannot be evaluated at these flows or this location without hydraulic evidence.</p></section><aside class="panel"><p class="action-label">INTERPRET THE RESULT</p><h2>Separate water delivery from habitat evidence</h2><p class="detail-copy">This run shows whether the hypothetical operation delivers the candidate. It does not establish an official obligation, legal fault or an accepted natural-flow reconstruction.</p><div class="timeline"><p><strong>Now · retain the calculation</strong>Keep the reconstructed forcing, source study, operating assumptions and complete daily results together.</p><p><strong>Before a real application</strong>Confirm the natural reference and infrastructure; test local hydraulics and biological suitability.</p><p><strong>Maintain and reassess</strong>Annual record maintenance; proposed full review within five years, or earlier when evidence changes.</p></div><button class="plain-button" data-view="compare">Back to method comparison →</button></aside></div>`;
}
(async()=>{
  try{
    const paths=['comparison-ecology.json','comparison-irrigation.json','comparison-stress-ecology.json','comparison-stress-irrigation.json','targets.json','targets-stress.json'];
    const responses=await Promise.all(paths.map(path=>fetch(path,{cache:'no-store'})));
    if(responses.some(r=>!r.ok))throw new Error('Verified result files are not available yet');
    const [ecology,irrigation,stressEcology,stressIrrigation,targets,stressTargets]=await Promise.all(responses.map(r=>r.json()));
    for(const [operation,key,result,derivation] of [['ecology','matched',ecology,targets],['irrigation','matched',irrigation,targets],['ecology','stress',stressEcology,stressTargets],['irrigation','stress',stressIrrigation,stressTargets]]){
      CalculatedData.validateComparison(result);CalculatedData.validateTargets(result,derivation);
      if(result.allocationPriority!==`${operation}-first`)throw new Error('Allocation priority does not match the selected policy');
      for(const scenario of Object.values(result.scenarios))for(const p of Object.values(scenario.methods)){
        if(!p.r2aFishyAssessment||!p.actualR2aM3s||p.actualR2aM3s.length!==365)throw new Error('R2a assessment is missing');
        if(p.ledger.some((r,i)=>r.date!==scenario.dates[i]||!Number.isSafeInteger(r.request_litres)||r.request_litres<0||!Number.isSafeInteger(r.r2a_litres)||r.r2a_litres<0||r.r2a_litres+r.return_litres!==r.downstream_litres))throw new Error('Section delivery evidence is inconsistent');
      }
      policyDatasets[operation][key]={data:result,targets:derivation};
    }
    calculation=ecology;
  }catch(error){calculationError=error.message;}
  render();
})();
